CREATE OR REPLACE FUNCTION law.reject_scope_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'law'
AS $function$
DECLARE
  column_name text;
BEGIN
  FOREACH column_name IN ARRAY TG_ARGV LOOP
    IF (to_jsonb(NEW) -> column_name) IS DISTINCT FROM (to_jsonb(OLD) -> column_name) THEN
      RAISE EXCEPTION '% 的归属字段 % 不允许变更', TG_TABLE_NAME, column_name USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION law.validate_message_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'law'
AS $function$
DECLARE
  message_case_id bigint;
  message_role text;
  conversation_user_id bigint;
  file_case_id bigint;
  file_uploader_id bigint;
BEGIN
  SELECT m.case_id, m.role, c.user_id INTO message_case_id, message_role, conversation_user_id
    FROM law.ai_messages m JOIN law.ai_conversations c ON c.id = m.conversation_id
    WHERE m.id = NEW.message_id FOR KEY SHARE OF m, c;
  IF NOT FOUND THEN
    RAISE EXCEPTION '附件所属消息不存在' USING ERRCODE = '23503';
  END IF;
  SELECT case_id, uploaded_by INTO file_case_id, file_uploader_id
    FROM law.files WHERE id = NEW.file_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '附件文件不存在' USING ERRCODE = '23503';
  END IF;
  IF message_role <> 'user' OR NEW.case_id IS DISTINCT FROM message_case_id
    OR NEW.case_id IS DISTINCT FROM file_case_id THEN
    RAISE EXCEPTION '附件仅可关联同案件范围的用户消息' USING ERRCODE = '23514';
  END IF;
  IF NEW.case_id IS NULL AND file_uploader_id IS DISTINCT FROM conversation_user_id THEN
    RAISE EXCEPTION '助手附件上传人必须为会话所有者' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION law.validate_message_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'law'
AS $function$
DECLARE
  conversation_case_id bigint;
BEGIN
  SELECT case_id INTO conversation_case_id FROM law.ai_conversations
    WHERE id = NEW.conversation_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '会话不存在' USING ERRCODE = '23503';
  END IF;
  IF NEW.case_id IS DISTINCT FROM conversation_case_id THEN
    RAISE EXCEPTION '消息案件归属必须与会话一致' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION law.validate_organization_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'law'
AS $function$
DECLARE
  org_ids bigint[];
  org_to_check bigint;
  owner_to_check bigint;
BEGIN
  IF TG_TABLE_NAME = 'organizations' THEN
    org_ids := CASE WHEN TG_OP = 'DELETE' THEN ARRAY[OLD.id] ELSE ARRAY[NEW.id] END;
  ELSIF TG_OP = 'INSERT' THEN
    org_ids := ARRAY[NEW.org_id];
  ELSIF TG_OP = 'DELETE' THEN
    org_ids := ARRAY[OLD.org_id];
  ELSE
    org_ids := ARRAY[OLD.org_id, NEW.org_id];
  END IF;
  FOREACH org_to_check IN ARRAY org_ids LOOP
    SELECT owner_user_id INTO owner_to_check FROM law.organizations
      WHERE id = org_to_check FOR UPDATE;
    IF FOUND AND NOT EXISTS (
      SELECT 1 FROM law.organization_members
      WHERE org_id = org_to_check AND user_id = owner_to_check AND role = 'owner' AND status = 'active'
    ) THEN
      RAISE EXCEPTION '组织 % 的所有者必须是有效 owner 成员', org_to_check USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NULL;
END;
$function$
